__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"default",{enumerable:!0,get:function(){return o}});var t=r(d[0]),n=r(d[1]),c=r(d[2]);function o(){const o=(0,t.c)(1);let u;return o[0]===Symbol.for("react.memo_cache_sentinel")?(u=(0,c.jsx)(n.PrivacyPolicy,{}),o[0]=u):u=o[0],u}},773,[785,865,6]);
__d(function(g,r,i,a,m,_e,d){"use strict";Object.defineProperty(_e,'__esModule',{value:!0}),_e.PrivacyPolicy=function(){const s=(0,e.c)(1);let l;s[0]===Symbol.for("react.memo_cache_sentinel")?(l=(0,t.jsx)(o.LegalPage,{title:"Pol\xedtica de tratamiento de datos personales",intro:`En OfiApp cuidamos tus datos. Aqu\xed te explicamos qu\xe9 datos recogemos, para qu\xe9 los usamos, con qui\xe9n los compartimos y c\xf3mo ejercer tus derechos. ${n.name} es responsable del tratamiento de tus datos en OfiApp.`,sections:c}),s[0]=l):l=s[0];return l};var e=r(d[0]),o=r(d[1]),s=r(d[2]),t=r(d[3]);const n=s.LegalEntity,c=[{title:'Responsable del tratamiento',body:[`\u2022 Responsable: ${n.name}`,`\u2022 NIT o c\xe9dula: ${(0,s.pending)(n.idNumber)}`,`\u2022 Domicilio: ${(0,s.pending)(n.city)}`,`\u2022 Direcci\xf3n: ${(0,s.pending)(n.address)}`,`\u2022 Tel\xe9fono: ${(0,s.pending)(n.phone)}`,`\u2022 Correo para temas de datos personales: ${n.email}`]},{title:'Qu\xe9 datos recogemos',body:['\u2022 Cuenta: nombre, correo electr\xf3nico y foto de perfil. Si entras con Google, solo recibimos esos tres datos; nunca tu contrase\xf1a.','\u2022 Perfil: n\xfamero de celular, municipio y si usas la app para contratar u ofrecer servicios.','\u2022 Si ofreces servicios: titular, descripci\xf3n, n\xfamero de WhatsApp, categor\xedas, municipios donde atiendes, a\xf1os de experiencia, precio de referencia y fotos de tus trabajos.','\u2022 Verificaci\xf3n (opcional, solo prestadores): fotos de tu c\xe9dula, una selfie sosteniendo tu c\xe9dula y tu certificado de antecedentes de la Polic\xeda Nacional.','\u2022 Uso de la app: solicitudes que publicas, respuestas, mensajes del chat, rese\xf1as, reportes, y registros de cu\xe1ndo alguien contacta o visita el perfil de un prestador.','\u2022 Ubicaci\xf3n aproximada: solo si das permiso, mientras usas la app, para ordenar prestadores por cercan\xeda. No la guardamos.','\u2022 Notificaciones: un identificador de tu dispositivo para enviarte avisos de mensajes y solicitudes.']},{title:'Para qu\xe9 los usamos',body:['\u2022 Crear y administrar tu cuenta y permitirte iniciar sesi\xf3n.','\u2022 Mostrar a los clientes los perfiles de los prestadores y conectarlos por chat, WhatsApp o llamada.','\u2022 Publicar solicitudes de servicio y enviarlas a los prestadores de la categor\xeda y el municipio.','\u2022 Verificar la identidad y los antecedentes de los prestadores que lo pidan, y mostrar los sellos correspondientes.','\u2022 Dar a cada prestador estad\xedsticas de visitas y contactos de su perfil.','\u2022 Moderar rese\xf1as y reportes, prevenir fraudes y mantener la seguridad de la comunidad.','\u2022 Enviarte notificaciones y c\xf3digos de acceso, y atender tus consultas.','No vendemos tus datos ni los usamos para publicidad de terceros.']},{title:'Datos sensibles y menores de edad',body:['La selfie con tu c\xe9dula (imagen de tu rostro) y el certificado de antecedentes son datos sensibles. Entregarlos es voluntario: no est\xe1s obligado a hacerlo, y solo se usan para verificar tu perfil. Solo el equipo de OfiApp encargado de la verificaci\xf3n puede verlos; nunca se muestran a otros usuarios.','OfiApp es para mayores de 18 a\xf1os. No recogemos a sabiendas datos de menores de edad.']},{title:'Qu\xe9 ven los dem\xe1s usuarios',body:['\u2022 Del prestador: nombre, foto, titular, descripci\xf3n, categor\xedas, municipios, experiencia, precio de referencia, fotos de trabajos, rese\xf1as, sellos de verificaci\xf3n y su n\xfamero de WhatsApp para que lo contacten.','\u2022 Del cliente: nombre y foto, solo para los prestadores con quienes conversa o que ven sus solicitudes. Tu n\xfamero de celular de cliente no se muestra a nadie.','Cuando contactas a alguien por WhatsApp o por llamada, esa conversaci\xf3n ocurre fuera de OfiApp y la rigen las condiciones de esos servicios.']},{title:'Con qui\xe9n compartimos datos',body:['Usamos proveedores que tratan datos por cuenta nuestra (encargados), con medidas de seguridad y solo para prestar el servicio:','\u2022 Supabase: base de datos, almacenamiento de archivos y autenticaci\xf3n.','\u2022 Google: inicio de sesi\xf3n con tu cuenta de Google, si lo eliges.','\u2022 Expo: env\xedo de notificaciones a tu celular.','\u2022 Proveedor de correo electr\xf3nico: env\xedo de los c\xf3digos de acceso.','Algunos de estos proveedores tienen servidores fuera de Colombia. Al aceptar esta pol\xedtica autorizas esa transferencia, que se hace a pa\xedses con niveles adecuados de protecci\xf3n o con las garant\xedas que exige la ley. Tambi\xe9n podemos entregar datos a autoridades cuando una ley u orden judicial lo exija.']},{title:'Tus derechos',body:['Como titular de tus datos (art\xedculo 8 de la Ley 1581 de 2012) puedes:','\u2022 Conocer, actualizar y corregir tus datos. La mayor\xeda los puedes editar t\xfa mismo en la app.','\u2022 Pedir prueba de la autorizaci\xf3n que nos diste.','\u2022 Saber c\xf3mo hemos usado tus datos.','\u2022 Revocar tu autorizaci\xf3n y pedir que borremos tus datos, incluida tu cuenta, cuando no exista un deber legal de conservarlos.','\u2022 Presentar quejas ante la Superintendencia de Industria y Comercio despu\xe9s de haber hecho tu consulta o reclamo ante nosotros.','\u2022 Acceder gratis a tus datos.']},{title:'C\xf3mo hacer consultas y reclamos',body:[`Escribe a ${n.email} desde el correo de tu cuenta, con tu nombre, lo que necesitas y, si es un reclamo, los hechos y documentos que lo soporten.`,'\u2022 Consultas: respondemos en m\xe1ximo 10 d\xedas h\xe1biles. Si no es posible, te avisamos el motivo y respondemos dentro de los 5 d\xedas h\xe1biles siguientes.','\u2022 Reclamos (correcci\xf3n, actualizaci\xf3n, supresi\xf3n o revocatoria): respondemos en m\xe1ximo 15 d\xedas h\xe1biles. Si no es posible, te avisamos el motivo y respondemos dentro de los 8 d\xedas h\xe1biles siguientes.','Para eliminar tu cuenta, escr\xedbenos con el asunto "Eliminar mi cuenta". La borramos junto con tu perfil, fotos, documentos de verificaci\xf3n y mensajes, salvo lo que la ley nos obligue a conservar.']},{title:'Cu\xe1nto tiempo los guardamos',body:['Conservamos tus datos mientras tengas una cuenta en OfiApp. Si la eliminas, los borramos, excepto la informaci\xf3n que debamos guardar por obligaci\xf3n legal o para atender reclamaciones, solo por el tiempo necesario.']},{title:'Seguridad',body:['Aplicamos controles de acceso para que cada usuario solo vea lo que le corresponde. Los documentos de verificaci\xf3n se guardan en un almacenamiento privado al que solo accede el equipo de verificaci\xf3n. Ning\xfan sistema es infalible: si detectamos un incidente que afecte tus datos, te avisaremos y lo informaremos a la autoridad cuando corresponda.']},{title:'Autorizaci\xf3n y cambios',body:['Al crear tu cuenta y continuar en OfiApp autorizas el tratamiento de tus datos seg\xfan esta pol\xedtica. Si la cambiamos de forma importante, te avisaremos en la app antes de que el cambio aplique.','Esta pol\xedtica se rige por la Ley 1581 de 2012, el Decreto 1074 de 2015 y las dem\xe1s normas colombianas sobre protecci\xf3n de datos personales.']}]},865,[785,866,858,6]);